window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"Zdo83eb0iZ4","speaker":"Cecilia Adout Majok Adeng","role":"Permanent Representative","country":"South Sudan","region":"Africa","url":"https://www.youtube.com/watch?v=Zdo83eb0iZ4","date":"20260928","title":"🇸🇸 South Sudan - Permanent Representative Addresses United Nations General Debate, 81st Session","seconds":1432,"words":2936,"counts":{"claims":40,"promises":2,"attacks":0},"topics":[{"topic":"South Sudan development","share":0.1345,"seconds":193},{"topic":"South Sudan peace","share":0.1047,"seconds":150},{"topic":"South Sudan independence","share":0.1042,"seconds":149},{"topic":"South Sudan diaspora","share":0.0934,"seconds":134},{"topic":"South Sudan history","share":0.0626,"seconds":90},{"topic":"South Sudan partnership","share":0.0549,"seconds":79},{"topic":"South Sudan elections","share":0.0488,"seconds":70},{"topic":"UN South Sudan","share":0.0483,"seconds":69},{"topic":"South Sudan sanctions","share":0.046,"seconds":66},{"topic":"South Sudan climate","share":0.0445,"seconds":64},{"topic":"UN Charter","share":0.0439,"seconds":63},{"topic":"South Sudan governance","share":0.0439,"seconds":63},{"topic":"Ceremony","share":0.0436,"seconds":62},{"topic":"UN Security Council reform","share":0.0424,"seconds":61},{"topic":"South Sudan peacekeeping","share":0.0423,"seconds":61},{"topic":"Sudan peace","share":0.042,"seconds":60}],"timeline":[[1,63,"Ceremony"],[64,127,"UN Charter"],[128,197,"UN South Sudan"],[199,289,"South Sudan history"],[289,379,"South Sudan peace"],[380,441,"South Sudan peace"],[442,503,"South Sudan independence"],[504,574,"South Sudan elections"],[575,638,"South Sudan governance"],[640,706,"South Sudan sanctions"],[707,767,"South Sudan peacekeeping"],[769,835,"South Sudan development"],[836,902,"South Sudan development"],[903,967,"South Sudan climate"],[968,1033,"South Sudan diaspora"],[1034,1103,"South Sudan diaspora"],[1104,1164,"Sudan peace"],[1164,1225,"UN Security Council reform"],[1226,1287,"South Sudan independence"],[1288,1348,"South Sudan development"],[1350,1428,"South Sudan partnership"],[1430,1457,"South Sudan independence"]],"stances":{"Ceremony":"Cecilia Adout Majok Adeng conveys greetings and appreciation from the President, government, and people of South Sudan to the assembly leadership.","UN Charter":"Cecilia Adout Majok Adeng affirms South Sudan's commitment to the UN Charter and emphasizes that trust is fundamental to peace.","UN South Sudan":"Cecilia Adout Majok Adeng states that restoring trust requires the UN to adapt its approaches to South Sudan's evolving circumstances and strengthen partnerships while respecting national ownership.","South Sudan history":"Cecilia Adout Majok Adeng states that South Sudan's history predates its 2011 independence and was shaped by decades of struggle, while acknowledging the contributions of various international and local actors to the peace process.","South Sudan peace":"Cecilia Adout Majok Adeng states that while political agreements are necessary, lasting peace in South Sudan also requires reconciliation, forgiveness, and courage.","South Sudan independence":"Cecilia Adout Majok Adeng states that the responsibility is to consolidate peace and strengthen institutions so people can determine their political future, noting that past difficulties have not extinguished the dreams of independence.","South Sudan elections":"Cecilia Adout Majok Adeng states that President Salva Kiir remains committed to holding general elections in December 2026 to conclude the transition period and allow democratic leadership selection.","South Sudan governance":"Cecilia Adout Majok Adeng asserts that South Sudan must transition from conflict to democratic governance through dialogue and elections rather than war.","South Sudan sanctions":"Cecilia Adout Majok Adeng argues that South Sudan seeks to build professional security forces under civilian authority and calls for the removal of restrictive measures like arms embargoes.","South Sudan peacekeeping":"Cecilia Adout Majok Adeng states that South Sudan aims to reduce dependence on international peacekeeping by building its own capacity through investment in key sectors.","South Sudan development":"Cecilia Adout Majok Adeng argues that sustainable peace in South Sudan requires investment in women, youth, and institutions to transition from crisis management to nation-building.","South Sudan climate":"Cecilia Adout Majok Adeng calls for predictable climate financing and emphasizes that South Sudan's youth and women are central to the nation's vision.","South Sudan diaspora":"Cecilia Adout Majok Adeng argues that the South Sudanese diaspora should be recognized as a national resource rather than solely through the lens of displacement, citing the basketball team's success as evidence of unity and excellence.","Sudan peace":"Cecilia Adout Majok Adeng states that South Sudan supports a lasting political solution and peaceful engagement for Sudan, rejecting military confrontation.","UN Security Council reform":"Cecilia Adout Majok Adeng argues that the current composition of the Security Council is inequitable and calls for appropriate representation for Africa and developing countries.","South Sudan partnership":"Cecilia Adout Majok Adeng calls for a partnership that strengthens national ownership and institutions while affirming South Sudan's commitment to the UN, Africa, and peace."},"claims":[{"t":29,"quote":"I bring you warm greetings and best wishes from his excellency President Salvakir Mayardit, the President of the Republic of South Sudan.","topic":"Ceremony","kind":"fact"},{"t":50,"quote":"I wish to congratulate Mr. President on your election to preside over the 81st session of the esteemed assembly of this general assembly.","topic":"Ceremony","kind":"fact"},{"t":93,"quote":"As the world's youngest nation and the 193rd member of the United Nations, South Sudan understands both the promises and the possibilities of multilateralism.","topic":"UN Charter","kind":"fact"},{"t":130,"quote":"We recognize and appreciate the contribution the United Nations has made to South Sudan from humanitarian assistance and protection of civilians to peaceuilding development and institutional support.","topic":"UN South Sudan","kind":"fact"},{"t":149,"quote":"Our experience has shown that international institutions can sometimes be slow to adjust to changing circumstances on the ground.","topic":"UN South Sudan","kind":"fact"},{"t":207,"quote":"The history of South Sudan did not begin with the independence of the 9th of July 2011. It was shaped by more than half of a century of struggle, sacrifices, displacement, and unwavering desire for freedom and self-determination.","topic":"South Sudan history","kind":"fact"},{"t":224,"quote":"Our late Dr. John Garang de Mabure summarized those aspirations of the struggle that when he spoke freedom, liberty, equality, justice, human rights and democracy.","topic":"South Sudan history","kind":"fact"},{"t":247,"quote":"The comprehensive peace agreement of 2005 provided the political framework that transformed that transformed struggles decades of struggles into a peaceful exercise of South Sudan therefore continues to recognize that the recognize the in indispens indispensable contribution of EGD and the African and our African Union brothers and sisters as well as the support of the troa the United States the United Kingdom and Norway and the wider international community Sudan also remembers the extraordinary contribution of the churches and faith-based leaders during some of the darkest years of the conflict.","topic":"South Sudan history","kind":"fact"},{"t":293,"quote":"They educated children. They assisted displaced communities. They mediated disputes and kept alive the belief that reconciliation was possible.","topic":"South Sudan peace","kind":"fact"},{"t":385,"quote":"South Sudan experienced internal conflict shortly after independence.","topic":"South Sudan peace","kind":"fact"},{"t":389,"quote":"Implementation of the of the militarized peace agreement has taken longer than originally intended or anticipated.","topic":"South Sudan peace","kind":"fact"},{"t":442,"quote":"The liberation struggle sought to give the people of South Sudan the right to determine their destiny.","topic":"South Sudan independence","kind":"fact"},{"t":462,"quote":"Mr. President, when the people of South Sudan voted for their independence, they voted they were voting for more than creation of a new state.","topic":"South Sudan independence","kind":"fact"},{"t":473,"quote":"They dreamt of a peace after generations of war.","topic":"South Sudan independence","kind":"fact"},{"t":497,"quote":"The difficulties of the last 15 years have been not extinguish not to extinguish those dreams.","topic":"South Sudan independence","kind":"fact"},{"t":510,"quote":"His Excellency President Zalva remains committed to paving the way towards general election scheduled for December 2026.","topic":"South Sudan elections","kind":"fact"},{"t":519,"quote":"These elections are intended to mark the conclusion of the transition period and provide the people of South Sudan the opportunity to choose democratically their own leaders.","topic":"South Sudan elections","kind":"fact"},{"t":584,"quote":"A resilient people who struggled for freedom, voted peacefully for independence, continue to aspire for peace, dignity, democracy and prosperity.","topic":"South Sudan governance","kind":"fact"},{"t":603,"quote":"Our journey therefore continues from liberation struggle to comprehensive peace agreement to the referendum to independence from conflict to peace and now from transition towards democratic governance.","topic":"South Sudan governance","kind":"fact"},{"t":648,"quote":"The government bears the primary responsibility for protecting its citizens.","topic":"South Sudan sanctions","kind":"fact"},{"t":667,"quote":"South Sudan objective is not militarization.","topic":"South Sudan sanctions","kind":"fact"},{"t":713,"quote":"We recognize the men and women who serve the United Nations flag who served under the United Nations flag particularly those who have lost their lives in the service of peace.","topic":"South Sudan peacekeeping","kind":"fact"},{"t":800,"quote":"at independence, South Sudan inherited extremely limited infrastructure and institutional capacity.","topic":"South Sudan development","kind":"fact"},{"t":814,"quote":"President Kier has placed particular emphasis on agriculture, infrastructure, education, healthcare, and economic","topic":"South Sudan development","kind":"fact"},{"t":824,"quote":"South Sudan possesses million of hectares of urbal land, significant water resources, livestocks, fishery, natural resources, and one of the youngest population in the world.","topic":"South Sudan development","kind":"fact"},{"t":849,"quote":"For a farmer, a road to a market is development. For a child, a functioning school is development. For a mother, access to health care is development. For a young person, employment is development.","topic":"South Sudan development","kind":"fact"},{"t":887,"quote":"Mr. President, South Sudan continues to face severe consequences from climate shocks despite contributing minimally to global emission.","topic":"South Sudan development","kind":"fact"},{"t":934,"quote":"The Roth peace agreement provided 35% representation for women in public institutions.","topic":"South Sudan climate","kind":"number"},{"t":985,"quote":"Our national basketball team, the bright star, demonstrated this before the world.","topic":"South Sudan diaspora","kind":"fact"},{"t":1000,"quote":"Under the leadership of Lur Deng and the South Sudan Basketball Federation, South Sudan qualified for the basketball world cup and subsequently the Olympic Games.","topic":"South Sudan diaspora","kind":"fact"},{"t":1034,"quote":"Engineers can contribute to infrastructure. Academians can strengthen education. Entrepreneurs can invest and create employment.","topic":"South Sudan diaspora","kind":"fact"},{"t":1044,"quote":"Technology professionals can conduct can connect South Sudan to digital economy.","topic":"South Sudan diaspora","kind":"fact"},{"t":1111,"quote":"South Sudan stand in solidarity with the people of Sudan. South Sudan and Sudan share his history, families, econ economic interests and one of the longest border in the region.","topic":"Sudan peace","kind":"fact"},{"t":1151,"quote":"Outstanding matters arising from the comprehensive peace agreement including the border issues and the final status of ABA also requires a peaceful engagement between South Sudan and Sudan.","topic":"Sudan peace","kind":"fact"},{"t":1177,"quote":"Africa with 54 member states remains without a permanent representation on the council.","topic":"UN Security Council reform","kind":"fact"},{"t":1213,"quote":"Mr. President 15 years after the independence, South Sudan remains a young nation undertaking the difficult work of building a state while consolidating peace and delivering development.","topic":"UN Security Council reform","kind":"fact"},{"t":1240,"quote":"The people of South Sudan chose independence through the ballots and his excellency president Salvakir Mayard carried the responsibility of leading South Sudan through referendum and into statehood.","topic":"South Sudan independence","kind":"fact"},{"t":1309,"quote":"Dr. John Garang once challenged the people of South Sudan to unite and dream That dream did not end with It continues today.","topic":"South Sudan development","kind":"fact"},{"t":1350,"quote":"We say stand with South Sudan again. But let this chapter be a partnership that strengthen national ownership, a partnership that build institutions, a partnership that recognizes progress while helping address remaining challenges.","topic":"South Sudan partnership","kind":"fact"},{"t":1379,"quote":"Managing means moving from conflict to institutions, from dependency to national capacity, and from transition towards democratic governance.","topic":"South Sudan partnership","kind":"fact"}],"promises":[{"t":1401,"quote":"South Sudan remains committed to the United Nations. South Sudan remain committed to Africa and South Sudan remain committed to peace","topic":"South Sudan partnership","kind":"promise"},{"t":1411,"quote":"under the leadership of his excellency President Salvak Mayard, South Sudan remains committed to the long journey of transforming the sacrifices of liberation into peace, dignity, development, democratic future for which the people of South Sudan have waited for generations.","topic":"South Sudan partnership","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"Ceremony","text":"I now give the floor uh to her excellency Cecilia Adut Majok Adeng, chair of delegation of South Sudan. Mr. President, Mr. Secretary General, excellencies, distinguished delegates, I bring you warm greetings and best wishes from his excellency President Salvakir Mayardit, the President of the Republic of South Sudan. And I bring you greetings from the government and the people of South Sudan together with a message of peace, unity, development, and unwavering commitment to international cooperation. I wish to congratulate Mr. President on your election to preside over the 81st session of the esteemed assembly of this general assembly. I also express South Sudan's appreciation to the secretary general."},{"t":64,"topic":"UN Charter","text":"His excellency Antonio Gutierrez has continued his service until the last speech he delivered here early this week, early last week. His commitment to the principle of the United Nations Charter stands with us. Mr. President, the theme of this session, restoring trust, managing transformation, a united nation that delivers for all, speaks directly to the experience and the aspiration of the people of South Sudan. As the world's youngest nation and the 193rd member of the United Nations, South Sudan understands both the promises and the possibilities of multilateralism. South Sudan also understand that trust is fundamental to peace. Trust among citizens, trust between citizens and their institutions, trust among nations, and trust between member states and the international institutions created to serve them. South Sudan remains committed to the United Nations and the purpose and the principle of its charter."},{"t":128,"topic":"UN South Sudan","text":"We recognize the and we recognize and appreciate the contribution the United Nations has made to South Sudan from humanitarian assistance and protection of civilians to peaceuilding development and institutional support. However, restoring trust also requires honest reflection. Our experience has shown that international institutions can sometimes be slow to adjust to changing circumstances on the ground. Approaches designed to respond to conflict must be capable of evolving as nations move towards peace, recovery, institution building and ownership for South Sudan. Therefore, restoring trust must mean strengthening partnership between the United Nations and member states, respecting national recognizing progress while acknowledging acknowledging remaining challenges and ensuring that international engagements ultimately strengthen the capacity of the nations to assume the responsibility of their own future."},{"t":199,"topic":"South Sudan history","text":"Mr. President to understand where South Sudan seeks to go, one must understand where South Sudan has came from. The history of South Sudan did not begin with the independence of the 9th of July 2011. It was shaped by more than half of a century of struggle, sacrifices, displacement, and unwavering desire for freedom and self-determination. Our late Dr. John Garang de Mabure summarized those aspirations of the struggle that when he spoke freedom, liberty, equality, justice, human rights and democracy. Those aspiration did not end with the independence. They remain part of the ongoing work of nation building. The comprehensive peace agreement of 2005 provided the political framework that transformed that transformed struggles decades of struggles into a peaceful exercise of South Sudan therefore continues to recognize that the recognize the in indispens indispensable contribution of EGD and the African and our African Union brothers and sisters as well as the support of the troa the United States the United Kingdom and Norway and the wider international community Sudan also remembers the extraordinary contribution of the churches and faith-based leaders during some of the darkest years of the conflict."},{"t":289,"topic":"South Sudan peace","text":"Churches remained with the people of South Sudan. They educated children. They assisted displaced communities. They mediated disputes and kept alive the belief that reconciliation was possible. That tradition continued with the historical and minical pilgrimage of peace to South Sudan by his holiness Pope Francis, the Archbishop of Canterbury and the moderator of the church of Scotland. Their message reinforced something that South Sudan has learned through painful experience. The message reinforced something that peace requires political agreements. But lasting peace also requires reconciliation, forgiveness and courage. Mr. President, his excellency President Zvakayad belongs to the generation that carried the struggle of liberation. Following the passing of Dr. John Garang deabure President Kier assumed the responsibility of safeguarding the comprehensive peace agreement and leading the people of South Sudan towards the referendum on On the on January 2011, the people of South Sudan overwhelmingly spoke through the ballot and on the 9th of July 2011, President Kir stood before the people as the flag of the Republic of South Sudan was raised for the first 15 years later, South Sudan has traveled a difficult road."},{"t":380,"topic":"South Sudan peace","text":"There has been achievements. There also have been setbacks. South Sudan experienced internal conflict shortly after independence. Implementation of the of the militarized peace agreement has taken longer than originally intended or anticipated. Economic and humanitarian challenges remain significant. The government does not deny these realities, but neither should these challenges be allowed to erase the progress made or define permanently the identity of the Republic of South Sudan. Throughout the transition period, President Kir has repeatedly made one commitment clear. He will not take South Sudan back to This commitment has guided his approach to peace process and remain fundamental to his vision for the next chapter of South Sudan. The mission before President Kir is therefore different from the mission of the liberation years."},{"t":442,"topic":"South Sudan independence","text":"The liberation struggle sought to give the people of South Sudan the right to determine their destiny. The responsibility today is to consolidate peace, strengthen institution, and create conditions through which the people of South Sudan can once again determine their political future through democratic means. Mr. President, when the people of South Sudan voted for their independence, they voted they were voting for more than creation of a new state. They were voting for a dream. They dreamt of a peace after generations of war. They dreamt of schools for their children, health care for their families, roads connecting their communities, food security and economic opportunities, justice and equality, strong institutions and a government whose authority ultimately drives from the will of its people. The difficulties of the last 15 years have been not extinguish not to extinguish those dreams."},{"t":504,"topic":"South Sudan elections","text":"they remain alive among the people of South Sudan. And it's it's precisely for this reason that His Excellency President Zalva remains committed to paving the way towards general election scheduled for December 2026. These elections are intended to mark the conclusion of the transition period and provide the people of South Sudan the opportunity to choose democratically their own leaders. We recognize the important work ahead. Electoral institutions require adequate resources. Political dialogue must continue. Security arrangements must advance. Civic and voter education must reach communities. Women and young people must participate meaningfully. Refugees and internally displaced person must not be left out. And an environment must be created to which political competition can occur peacefully. The government remains committed to working towards these objectives. For far too long, South Sudan has often been seen internationally through the lens of conflict, humanitarian needs, and political crisis."},{"t":575,"topic":"South Sudan governance","text":"President Kir's vision is to create the condition in which the world can once again see the people of South Sudan for who they truly are. A resilient people who struggled for freedom, voted peacefully for independence, continue to aspire for peace, dignity, democracy and prosperity. The people of South Sudan must increasingly speak for themselves and they must speak through the ballot. Our journey therefore continues from liberation struggle to comprehensive peace agreement to the referendum to independence from conflict to peace and now from transition towards democratic governance. Mr. President, the message of President K remains clear. South Sudan must not return to war. Political disagreement must not be addressed. Political disagreement must be addressed through dialogue. Political competition must never again become armed The ballot must replace the bullets."},{"t":640,"topic":"South Sudan sanctions","text":"South Sudan recognizes that conducting peaceful elections requires security and strong institutions. The government bears the primary responsibility for protecting its citizens. Maintaining public order and safeguarding the electoral process. South Sudan therefore continues to call for constructive engagements with the security council concerning restrictive measures including the arms embargo. South Sudan objective is not militarization. The objective is to develop professional unified disciplined and accountable security forces operating under the civilian authority and the rule of law. South Sudan believes that that accountability and national capacity should reinforce themselves. We therefore call for the lifting of all restrictive measures. Sanctions and a sanction must be instruments for clear defined objectives. They should not become permanent substitute for political engagements and institution buildings."},{"t":707,"topic":"South Sudan peacekeeping","text":"Mr. President South Sudan remains grateful for the contribution of the United Nation mission in South Sudan. We recognize the men and women who serve the United Nations flag who served under the United Nations flag particularly those who have lost their lives in the service of peace. As South Sudan advance its transition international international engagement al must also evolve. President Kir's vision is not for South Sudan to remain indef indefinitely dependent upon international peacekeeping. The objective must be a South Sudan capable of sustaining its own peacekeeping. South Sudan therefore calls for a greater emphasis on peace building, institutional development, continu continuous capacity building and we are also keen to establishing partnership. Invest in South Sudan police and judiciary. Invest in public administration. Invest in education and healthcare. Invest in infrastructure."},{"t":769,"topic":"South Sudan development","text":"Invest in women and young people. invest in institutions that will sustain peace long after peacekeepers have departed. The ultimate measures of a successful peacekeeping should be the establishment of condition under which peacekeeping is no longer required. South Sudan therefore seeks the response seek a responsible transition man from managing crisis towards building a lasting national capacity. Mr. President, peace cannot be sustained without development. And at independence, South Sudan inherited extremely limited infrastructure and institutional capacity. Nation building, state building and service delivery have therefore have to proceed President Kier has placed particular emphasis on agriculture, infrastructure, education, healthcare, and economic South Sudan possesses million of hectares of urbal land, significant water resources, livestocks, fishery, natural resources, and one of the youngest population in the world."},{"t":836,"topic":"South Sudan development","text":"South Sudan therefore seeks to transition progressively from humanitarian dependency to self reliance and towards a sustainable development and For a farmer, a road to a market is development. For a child, a functioning school is development. For a mother, access to health care is development. For a young person, employment is development. And for South Sudan, development is one of the strongest foundation for lasting peace. We therefore invite international partners and responsible investors to look beyond South Sudan's current challenges and recognize its potential. Do not ask only what South Sudan needs. Ask what South Sudan can offer. Mr. President, South Sudan continues to face severe consequences from climate shocks despite contributing minimally to global emission. Recurring floods, droughts, displacement, and food insecurity are affecting millions of South Sudin."},{"t":903,"topic":"South Sudan climate","text":"South Sudan therefore reiterates its call for predictable and accessible climate financing, investment and adaptation, resilient infrastructure, renewable energy, agriculture and technology transfer. Climate justice must reflect not only in commitments but in the Mr. President South Sudan and young people, women and young people of South Sudan are central to President K's vision. The Roth peace agreement provided 35% representation for women in public institutions. South Sudan continues on working to translate those commitment into meaningful participation at all levels. South Sudan also is an overwhelmingly young population. These young people should not inherit a conflict of previous generation. They should inherit opportunities of peace. Education, vocational training, technology, entrepreneurship, agriculture, and sports."},{"t":968,"topic":"South Sudan diaspora","text":"That is the future they deserve. Mr. President, decades of conflict scattered South Sudin across the world. But South Sudin diaspora should not be viewed only through the history of displacement. It is also an extraordinary national resources. Our national basketball team, the bright star, demonstrated this before the world. Saludanese whose journey had taken them across different countries and and continents came together under one flag. Under the leadership of Lur Deng and the South Sudan Basketball Federation, South Sudan qualified for the basketball world cup and subsequently the Olympic Games. They showed the world the image of South Sudan not conflict, not displacement but discipline, unity and excellence. The experience the experience offers this experience offer a model for national South Sudan doctors abroad can contribute to healthcare."},{"t":1034,"topic":"South Sudan diaspora","text":"Engineers can contribute to infrastructure. Academians can strengthen education. Entrepreneurs can invest and create employment. Technology professionals can conduct can connect South Sudan to digital economy. And successful South Sudinis around the world can mentor the next generation. to the international community. We need to create a stronger partnership that would enable South Sudan diaspora to transfer their skills and professional experience in order to contribute to the ongoing development in the Republic of South Sudan. To the South Sudanese diaspora, our message is simple. South Sudan needs you. Bring your knowledge home. Bring your experience home. Bring your investment home. And bring your networks Where physical return is not possible, allow your skills and experience to contribute to South Sudan. The same spirits, the same spirits that brought South Sudanese athletes from around the world together under one flag can help bring South Sudin expertise together for one national purpose."},{"t":1104,"topic":"Sudan peace","text":"South Sudan greatest resources is ultimately its people both at home and abroad. Mr. President South Sudan stand in solidarity with the people of Sudan. South Sudan and Sudan share his history, families, econ economic interests and one of the longest border in the region. South Sudan therefore reiterates it ongoing and continued full support for a lasting peace in the Sudan. South Sudan knows from the experience that military confrontation ultimately requires a political solution. Even the longest conflict must eventually reach a negotiated settlement. South Sudan therefore supports regional and international efforts aim at achieving peace in Sudan. Outstanding matters arising from the comprehensive peace agreement including the border issues and the final status of ABA also requires a peaceful engagement between South Sudan and Sudan. Mr."},{"t":1164,"topic":"UN Security Council reform","text":"President, restoring trust also requires reform of institutions of global governance. The composition of the security council does not equitably reflect the realities of today. Africa with 54 member states remains without a permanent representation on the council. South Sudan therefore reinforms its support for the common African position. Africa must be appropriately represented in both permanent and non-permanent categories. Similarly, developing countries must have a stronger voice in international financial institutions and decisions concerning development, financing, debt, climate, and technology. Reforms do not weaken Reforms strengthen its legitimacy. Mr. President 15 years after the independence, South Sudan remains a young nation undertaking the difficult work of building a state while consolidating peace and delivering development."},{"t":1226,"topic":"South Sudan independence","text":"The journey has not been easy, but the liberation the liberation the liberation generation fought for freedom. The generation of the comprehensive peace agreement secured the pathway to self-determination. The people of South Sudan chose independence through the ballots and his excellency president Salvakir Mayard carried the responsibility of leading South Sudan through referendum and into statehood. Today, President Kir's vision is directed towards another historical to preserve peace, strengthen national institutions, pave the way towards elections through which the people of South Sudan can determine the next chapter of their nation. This ultimately this ultimately about completing the promise of independence. A South Sudan at peace with itself. A South Sudan governs through strong institution. A South Sudan where political competition does not lead to war."},{"t":1288,"topic":"South Sudan development","text":"A South Sudan where women participate fully. And where young people have opportunities, where refugees can return home, where the diaspora can contribute to national development, and where children grow up knowing South Sudan, not through the marmoirs of peace, of war, but through the possibilities of peace. Dr. John Garang once challenged the people of South Sudan to unite and dream That dream did not end with It continues today. And today the responsibility of President K is and his government is the political leadership is indeed is that people of South Sudan must dream and must have a functioning peaceful and a prosperous South Sudan. to our international partners who stood with us during our liberation struggle and during the comprehensive peace agreement and during the referendum and at independence."},{"t":1350,"topic":"South Sudan partnership","text":"We say stand with South Sudan again. But let this chapter be a partnership that strengthen national ownership, a partnership that build institutions, a partnership that recognizes progress while helping address remaining challenges. A partnership that enables South Sudan progressively to stand on its own. Mr. President, for South Sudan, restoring trust means delivering on the promises of peace. Managing means moving from conflict to institutions, from dependency to national capacity, and from transition towards democratic governance. and a United Nations that deliver for all means ultimately help nations develop the capacity to deliver for their own people. South Sudan remains committed to the United Nations. South Sudan remain committed to Africa and South Sudan remain committed to peace and under the leadership of his excellency President Salvak Mayard, South Sudan remains committed to the long journey of transforming the sacrifices of liberation into peace, dignity, development, democratic future for which the people of South Sudan have waited for generations."},{"t":1430,"topic":"South Sudan independence","text":"That is the promise of independence. That is the responsibility of this generation and that is the future South Sudan seek to build. May the all lord Almighty bless the people of South Sudan and may the Lord Almighty bless all the nation represented in this assembly. I thank you for your kind attention. I thank the chair of delegation of South"}],"compare":[{"topic":"UN & its reform","share":0.1407,"mean":0.2051,"rank":122,"others":170},{"topic":"Sudan","share":0.0439,"mean":0.0071,"rank":16,"others":15}]};
